        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String s = scanner.next();

        // We need to count the number of contiguous substrings that return to origin.
        // A substring from index i to j (inclusive) returns to origin if the net displacement is (0,0).
        // Let prefix[i] be the position after executing commands 0 to i-1.
        // Then substring from i to j (0-indexed, inclusive) has net displacement = prefix[j+1] - prefix[i].
        // So we need prefix[j+1] == prefix[i].
        // We can compute prefix positions and count pairs (i, j) such that prefix[i] == prefix[j+1] and i < j+1.
        // Actually, let's define prefix[0] = (0,0), prefix[k] = position after first k commands.
        // A substring from index i to j (0-indexed) corresponds to prefix[j+1] - prefix[i] = (0,0), so prefix[j+1] == prefix[i].
        // The substring is non-empty, so j >= i, which means j+1 > i, so we need i < j+1.
        // So we count pairs (i, k) where 0 <= i < k <= n and prefix[i] == prefix[k].

        // Compute prefix positions
        int[] px = new int[n + 1];
        int[] py = new int[n + 1];
        px[0] = 0;
        py[0] = 0;

        for (int i = 0; i < n; i++) {
            px[i + 1] = px[i];
            py[i + 1] = py[i];
            switch (s.charAt(i)) {
                case 'U':
                    py[i + 1]++;
                    break;
                case 'D':
                    py[i + 1]--;
                    break;
                case 'R':
                    px[i + 1]++;
                    break;
                case 'L':
                    px[i + 1]--;
                    break;
            }
        }

        // Count pairs (i, k) with i < k and prefix[i] == prefix[k]
        // Use a map to store counts of each position seen so far
        Map<String, Integer> countMap = new HashMap<>();
        long result = 0;

        // Start with prefix[0]
        countMap.put(posKey(px[0], py[0]), 1);

        for (int k = 1; k <= n; k++) {
            String key = posKey(px[k], py[k]);
            Integer count = countMap.get(key);
            if (count != null) {
                result += count;
            }
            countMap.put(key, (count != null ? count : 0) + 1);
        }

        System.out.println(result);
    }

    private static String posKey(int x, int y) {
        return x + "," + y;
    }
}
